CASES = []
def t(action, owners=(), deadline=None, status='committed', condition=None):
    return dict(action=action, owners=list(owners), deadline=deadline, status=status, condition=condition)
def c(topic, before, after, old, final, left, partial, background, neighbor):
    CASES.append(dict(topic=topic,before=before,after=after,old=old,final=final,left=left,partial=partial,background=background,neighbor=neighbor))

